package org.diy.liferecorder;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** Live view of durable jobs; user actions never silently authorize a provider request. */
public final class TaskCenterActivity extends AppScreen {
 private final Handler updates=new Handler();private LinearLayout list;private Button runAll;private TextView summary,transferText,downloadText;private LinearLayout downloadCard;private ProgressBar downloadBar;private ProgressBar transferBar;private final Map<String,TextView> descriptions=new HashMap<>();private final Map<String,ProgressBar> bars=new HashMap<>();private String signature="",filter="active";private long lastAutoCheck;
 private final java.util.concurrent.ExecutorService queries=java.util.concurrent.Executors.newSingleThreadExecutor();
 private boolean queryPending,visible;private int viewVersion,pageSize=100;

 public void onCreate(Bundle b){super.onCreate(b);render();}
 private void render(){viewVersion++;frame("任务中心");button(body,"‹ 返回",this::finish);body.addView(title("任务中心",25));body.addView(text("查看传输、离线转写和 API 处理进度",13,MUTED));LinearLayout transfer=card(body);transfer.addView(title("手表文件接收",17));transferText=text("",13,MUTED);transfer.addView(transferText);transferBar=progressBar(transfer);downloadCard=card(body);downloadCard.addView(title("离线资源下载",17));downloadText=text("",12,MUTED);downloadCard.addView(downloadText);downloadBar=progressBar(downloadCard);button(downloadCard,"管理资源下载",()->startActivity(new Intent(this,OfflineActivity.class).putExtra("section","packs")));summary=text("",13,SAGE);body.addView(summary);runAll=primary(body,"立即处理等待中的离线任务",()->{try{OfflineScheduler.runNow(this,"");notice.setText("已开始前台处理，可在通知栏查看进度");}catch(Exception e){notice.setText(e.getMessage());}});HorizontalScrollView fs=new HorizontalScrollView(this);fs.setHorizontalScrollBarEnabled(false);LinearLayout filters=row();fs.addView(filters);body.addView(fs);for(String id:new String[]{"active","done","failed","all"}){TextView chip=pill(filters,id.equals("active")?"处理中与等待中":id.equals("done")?"已完成":id.equals("failed")?"失败与已取消":"全部记录",filter.equals(id)?PAPER:MUTED,filter.equals(id)?ACCENT:TINT);chip.setMinHeight(dp(44));chip.setGravity(Gravity.CENTER);chip.setOnClickListener(v->{filter=id;pageSize=100;signature="";render();});}list=column();body.addView(list);signature="";refresh();}
 private void refresh(){
    downloadCard.setVisibility(ModelDownloadService.active.isEmpty()?View.GONE:View.VISIBLE);
    setLabel(downloadText,ModelDownloadService.status);progress(downloadBar,ModelDownloadService.downloadDone,ModelDownloadService.downloadTotal);
    TransferProgress.Snapshot transfer=TransferProgress.current;setLabel(transferText,transfer.label());
    transferBar.setVisibility(transfer.active||transfer.total>0?View.VISIBLE:View.GONE);progress(transferBar,transfer.received,transfer.total);
    if(queryPending||isDestroyed())return;
    queryPending=true;final int version=viewVersion,requestedSize=pageSize;final String requestedFilter=filter;
    queries.execute(()->{
      try(RecordStore db=new RecordStore(getApplicationContext())){
        JSONArray counts=db.rows("SELECT status,count(*) AS n FROM jobs GROUP BY status");
        boolean local=db.rows("SELECT id FROM jobs WHERE type='local_asr' AND status='queued' LIMIT 1").length()>0;
        JSONArray jobs=db.rows("SELECT j.id,j.source,j.type,j.status,j.error,j.created,j.stage,j.progress_done,j.progress_total,j.progress_unit,j.updated,CASE WHEN j.type='local_asr' THEN j.input ELSE '{}' END AS input,j.automatic,a.title AS audio_title FROM jobs j LEFT JOIN audio a ON j.source=a.id "+(requestedFilter.equals("active")?"WHERE j.status IN ('queued','running') ":requestedFilter.equals("done")?"WHERE j.status='done' ":requestedFilter.equals("failed")?"WHERE j.status IN ('failed','uncertain','cancelled') ":"")+"ORDER BY CASE j.status WHEN 'running' THEN 0 WHEN 'queued' THEN 1 ELSE 2 END,j.created DESC LIMIT "+requestedSize);
        for(int n=0;n<jobs.length();n++){JSONObject j=jobs.getJSONObject(n);if(j.optString("type").equals("local_asr")&&j.optString("status").equals("queued"))j.put("waiting_text",OfflineProcessor.waiting(this,j));}
        runOnUiThread(()->{queryPending=false;if(!visible||isDestroyed()||version!=viewVersion)return;
          try{
            int waiting=0,running=0,done=0;for(int n=0;n<counts.length();n++){JSONObject row=counts.getJSONObject(n);switch(row.optString("status")){case "queued":waiting=row.optInt("n");break;case "running":running=row.optInt("n");break;case "done":done=row.optInt("n");break;}}
            runAll.setEnabled(local);setLabel(summary,"处理中 "+running+" · 等待中 "+waiting+" · 已完成 "+done);
            applyJobs(jobs);
          }catch(Exception error){notice.setText("任务状态读取失败，请稍后刷新");}
        });
      }catch(Exception error){runOnUiThread(()->{queryPending=false;if(visible&&!isDestroyed())notice.setText("任务状态读取失败，请稍后刷新");});}
    });
 }
 private void applyJobs(JSONArray jobs)throws Exception{
    StringBuilder key=new StringBuilder(filter);for(int n=0;n<jobs.length();n++){JSONObject j=jobs.getJSONObject(n);key.append(j.optString("id")).append(j.optString("status")).append(j.optString("error"));}if(!signature.equals(key.toString())){int y=scroll.getScrollY();signature=key.toString();list.removeAllViews();descriptions.clear();bars.clear();if(jobs.length()==0){LinearLayout empty=card(list);empty.addView(text("这里暂时没有任务。新收到的录音和你发起的处理会出现在这里。",14,MUTED));}for(int n=0;n<jobs.length();n++)jobCard(jobs.getJSONObject(n));if(jobs.length()==pageSize)button(list,"显示更多任务",()->{pageSize+=100;signature="";refresh();});scroll.post(()->scroll.scrollTo(0,y));}for(int n=0;n<jobs.length();n++){JSONObject j=jobs.getJSONObject(n);String id=j.optString("id"),state=j.optString("status"),value;if(state.equals("queued")&&j.optString("type").equals("local_asr"))value=j.optString("waiting_text");else if(state.equals("running")||state.equals("done"))value=j.optString("stage").isEmpty()?(state.equals("done")?"结果已生成":"请求处理中"):TaskProgress.describe(j);else value=j.optString("error");TextView line=descriptions.get(id);if(line!=null)setLabel(line,label(state)+" · "+value);ProgressBar bar=bars.get(id);if(bar!=null){bar.setVisibility(state.equals("running")||state.equals("done")?View.VISIBLE:View.GONE);if(state.equals("done")){bar.setIndeterminate(false);bar.setProgress(1000);}else progress(bar,j.optLong("progress_done"),j.optLong("progress_total"));}}
 }
 private void jobCard(JSONObject j){String id=j.optString("id"),type=j.optString("type"),state=j.optString("status"),source=j.optString("source");LinearLayout c=card(list);c.addView(title(AudioReview.object(j.optString("input")).optBoolean("speaker_only")?"仅重新匹配声纹":label(type),17));c.addView(rawText(j.isNull("audio_title")?AppLanguage.text(this,"所选原文与来源"):j.optString("audio_title"),13,MUTED));TextView description=text("",12,SAGE);c.addView(description);descriptions.put(id,description);ProgressBar bar=progressBar(c);bars.put(id,bar);if(state.equals("queued")&&type.equals("local_asr"))primary(c,"立即处理这一项",()->{try{OfflineScheduler.runNow(this,id);refresh();}catch(Exception e){notice.setText(e.getMessage());}});if(state.equals("queued")||state.equals("running"))button(c,"暂停 / 取消此任务",()->{android.content.ContentValues values=new android.content.ContentValues();values.put("status","cancelled");if(store.getWritableDatabase().update("jobs",values,"id=? AND status IN ('queued','running')",new String[]{id})>0)TaskProgress.set(store,id,"已由你取消",0,0,"");refresh();});if(state.equals("failed")||state.equals("uncertain")||state.equals("cancelled"))button(c,"重新确认后重试",()->retry(j));if(!source.isEmpty())button(c,"查看来源与结果",()->openRecord(source));else if(type.equals("hourly_summary"))button(c,"查看逐小时总结",()->startActivity(new Intent(this,HourlySummaryActivity.class).putExtra("job_id",id)));else if(state.equals("done"))button(c,"查看结果",()->showResult(id));if(!j.optString("error").isEmpty())button(c,"查看原因",()->message("任务说明",j.optString("error")));}
 private void showResult(String id){try{messageRaw("处理结果",store.rows("SELECT result FROM jobs WHERE id=?",id).getJSONObject(0).optString("result"));}catch(Exception e){notice.setText("结果暂不可用");}}
 private void retry(JSONObject j){try{if(j.optString("type").equals("hourly_summary")){startActivity(new Intent(this,HourlySummaryActivity.class).putExtra("job_id",j.optString("id")));return;}j=store.rows("SELECT * FROM jobs WHERE id=?",j.getString("id")).getJSONObject(0);String type=j.getString("type"),source=j.getString("source");JSONObject input=new JSONObject(j.getString("input"));input.put("automatic",false);if(type.equals("local_asr")){OfflinePacks packs=new OfflinePacks(this);if(input.optBoolean("speaker_only")?!packs.ready("speaker"):(packs.selected().isEmpty()||!packs.ready(packs.selected()))){startActivity(new Intent(this,OfflineActivity.class).putExtra("section","packs"));return;}if(!input.optBoolean("speaker_only"))input.put("pack",packs.selected());input.put("automatic",false);}else if(!type.equals("vad")){JSONObject nextProvider=new ProviderClient(this).snapshot(type.equals("asr")?"asr":"llm"),previous=input.optJSONObject("provider");if(type.equals("asr")&&previous!=null&&(!previous.optString("endpoint").equals(nextProvider.optString("endpoint"))||previous.optLong("revision")!=nextProvider.optLong("revision"))){input.remove("remote_job_id");input.remove("remote_recording_id");}input.put("provider",nextProvider);}if(type.equals("analysis"))input.put("transcript",store.audio(source).getString("transcript"));if(type.equals("asr"))input.put("transcript_before",store.audio(source).getString("transcript"));confirmJob(source,type,input,()->{signature="";refresh();});}catch(Exception e){notice.setText("来源已删除或配置不可用");}}
 private final Runnable tick=new Runnable(){public void run(){if(SystemClock.elapsedRealtime()-lastAutoCheck>=3000){lastAutoCheck=SystemClock.elapsedRealtime();OfflineScheduler.runVisible(TaskCenterActivity.this);}refresh();updates.postDelayed(this,1500);}};
 public void onResume(){super.onResume();visible=true;updates.removeCallbacks(tick);updates.post(tick);}public void onPause(){visible=false;viewVersion++;updates.removeCallbacks(tick);super.onPause();}
 public void onDestroy(){queries.shutdown();super.onDestroy();}
}
